import numpy as np

# ==========================================
# 1. CORE FUNCTIONS THIS SHIT IS FOR ORNL
# ==========================================

def calculate_split_organ(E1, U1_pct, E2, U2_pct, organ_name):
    # Convert percentages to decimals
    U1, U2 = U1_pct / 100, U2_pct / 100
    
    # Calculate Net Edep for all 30 batches
    E_net = E1 + E2
    
    # Calculate Quadrature Uncertainty for all 30 batches
    sigma_tot = np.sqrt((E1 * U1)**2 + (E2 * U2)**2)
    R_net_pct = (sigma_tot / E_net) * 100
    
    # Calculate the True Variance Test metrics
    mean_R_T = np.mean(R_net_pct)
    rsd_edep = (np.std(E_net, ddof=1) / np.mean(E_net)) * 100
    
    print(f"--- {organ_name.upper()} ---")
    print(f"Mean of Uncertainties (R_T): {mean_R_T:.4f}%")
    print(f"Empirical RSD of Edep:       {rsd_edep:.4f}%\n")
    
    return E_net, R_net_pct

def calculate_lungs(E_LL, U_LL, E_LHP, U_LHP, E_RL, U_RL, E_RHP, U_RHP):
    # Convert percentages to decimals
    U_LL, U_LHP = U_LL / 100, U_LHP / 100
    U_RL, U_RHP = U_RL / 100, U_RHP / 100
    
    # Calculate Net Edep (Subtraction)
    E_net_lungs = (E_LL - E_LHP) + (E_RL - E_RHP)
    
    # Calculate Quadrature Uncertainty (Addition)
    sigma_lungs = np.sqrt((E_LL * U_LL)**2 + (E_LHP * U_LHP)**2 + 
                          (E_RL * U_RL)**2 + (E_RHP * U_RHP)**2)
    R_net_lungs_pct = (sigma_lungs / E_net_lungs) * 100
    
    # Calculate the True Variance Test metrics
    mean_R_T = np.mean(R_net_lungs_pct)
    rsd_edep = (np.std(E_net_lungs, ddof=1) / np.mean(E_net_lungs)) * 100
    
    print(f"--- NET LUNGS ---")
    print(f"Mean of Uncertainties (R_T): {mean_R_T:.4f}%")
    print(f"Empirical RSD of Edep:       {rsd_edep:.4f}%\n")
    
    return E_net_lungs, R_net_lungs_pct


